1	import type {WebSocket} from 'ws';
2	import type {ChatSession, SessionEntry} from '../../types/session.js';
3	import type {SessionLookup, SessionStore} from '../../types/sessionStore.js';
4	import type {ConnectedMessage} from '../../types/messages.js';
5	import {sendSkip, sendUpsert} from './sender.js';
6	import {log} from '../../shared/logger.js';
7	
8	/** Opt-in resume. GDPR: enabling it keeps conversation content past disconnect, so the consumer owns the retention bound — set it with the store's `maxAgeMs` and erasure methods and see re-cinq/HALEngine#41; an unbounded retained store is a retention breach, not a memory leak. */
9	export interface SessionResumeOptions {
10	  enabled: boolean;
11	  /** With no `?sessionId=`, rejoin the user's most recently active session (the store's `latestFor`) instead of starting one; `?new=1` still starts one. */
12	  latest?: boolean;
13	}
14	
15	/** What `onConnect` learns about a connection besides its session. */
16	export interface ConnectInfo {
17	  /** `true` when the connection rejoined a stored session, the one `?sessionId=` named or the user's latest; `false` for a new session. */
18	  resumed: boolean;
19	}
20	
21	interface Requester {
22	  requestedSessionId?: string;
23	  startNewSession?: boolean;
24	  userId: string | number;
25	}
26	
27	type ResumeFailure = NonNullable<ConnectedMessage['resumeFailure']>;
28	
29	/** The session rejoined, or, for a named id that was not, why. */
30	export interface ResumeOutcome {
31	  session?: ChatSession;
32	  failure?: ResumeFailure;
33	}
34	
35	// Only the requester's own session is rejoined; a miss, a store failure and a not-yours all read as no resume.
36	export async function resumableSession(
37	  store: SessionStore,
38	  requester: Requester,
39	  options?: SessionResumeOptions
40	): Promise<ResumeOutcome> {
41	  const found = await storedSession(store, requester, options);
42	  if (found === undefined) return {};
43	  if (found.status === 'active' && isOwnedBy(found, requester)) return {session: found.session};
44	  // The latest-session default names no id, so there is no failure to report.
45	  if (requester.requestedSessionId === undefined) return {};
46	  return {failure: failureOf(found, requester)};
47	}
48	
49	async function storedSession(
50	  store: SessionStore,
51	  requester: Requester,
52	  options: SessionResumeOptions | undefined
53	): Promise<SessionLookup | undefined> {
54	  try {
