1	import type {ChatSession} from '../../types/session.js';
2	import type {
3	  SessionStore,
4	  SessionCreateOptions,
5	  SessionListOptions,
6	  SessionLookup,
7	  SessionSummary,
8	} from '../../types/sessionStore.js';
9	import {cappedLimit, cursorAt, newestFirst, sitsAfter} from './sessionListWindow.js';
10	
11	// Eight hours: a memory bound, not a retention decision (specs/hal-engine-session-lifetime/spec.md).
12	const DEFAULT_MAX_AGE_MS = 8 * 60 * 60 * 1000;
13	
14	export interface InMemorySessionStoreOptions {
15	  maxAgeMs?: number;
16	}
17	
18	// The creation time is held beside the session rather than on it, so it never reaches the public ChatSession.
19	interface HeldSession {
20	  session: ChatSession;
21	  createdAt: number;
22	}
23	
24	export class InMemorySessionStore implements SessionStore {
25	  private readonly sessions = new Map<string, HeldSession>();
26	  private readonly maxAgeMs: number;
27	
28	  constructor(options: InMemorySessionStoreOptions = {}) {
29	    this.maxAgeMs = options.maxAgeMs ?? DEFAULT_MAX_AGE_MS;
30	  }
31	
32	  create(sessionId: string, userId: string | number, options?: SessionCreateOptions): ChatSession {
33	    this.sweepExpired();
34	
35	    const session: ChatSession = {
36	      sessionId,
37	      userId,
38	      entries: [],
39	      authHeaders: options?.authHeaders,
40	      workspaceId: options?.workspaceId,
41	    };
42	    this.sessions.set(sessionId, {session, createdAt: Date.now()});
43	    return session;
44	  }
45	
46	  get(sessionId: string): ChatSession | undefined {
47	    const held = this.sessions.get(sessionId);
48	    if (held === undefined) return undefined;
49	    if (!this.hasExpired(held)) return held.session;
50	
51	    this.sessions.delete(sessionId);
52	    return undefined;
53	  }
54	
55	  /** One shot: a session past `maxAgeMs` answers `expired` once and is evicted, never kept as a tombstone. */
56	  lookup(sessionId: string): SessionLookup {
57	    const held = this.sessions.get(sessionId);
58	    if (held === undefined) return {status: 'missing'};
59	    if (!this.hasExpired(held)) return {status: 'active', session: held.session};
60	
61	    this.sessions.delete(sessionId);
62	    return {status: 'expired', userId: held.session.userId};
63	  }
64	
65	  delete(sessionId: string): boolean {
66	    return this.sessions.delete(sessionId);
67	  }
68	
69	  // Eviction and erasure coincide for a store that is only a cache; they do not for a durable one.
70	  evict(sessionId: string): boolean {
71	    return this.sessions.delete(sessionId);
72	  }
73	
74	  count(): number {
75	    return this.sessions.size;
76	  }
77	
78	  clear(): void {
79	    this.sessions.clear();
80	  }
81	
82	  /** Summaries of the user's live sessions, newest activity first, by the same activity `latestFor` reads. */
83	  listFor(userId: string | number, options?: SessionListOptions): SessionSummary[] {
84	    const limit = cappedLimit(options?.limit);
85	    if (limit === 0) return [];
86	
87	    const ordered = this.ownedBy(userId).map(summaryOf).sort(newestFirst);
88	    const before = options?.before;
89	    if (before === undefined) return ordered.slice(0, limit);
90	
91	    const at = cursorAt(before);
92	    return ordered.filter(summary => sitsAfter(summary, at, before.sessionId)).slice(0, limit);
93	  }
94	
95	  /** The user's most recently active session that has not aged out: its newest entry decides, or its creation if it has none. */
96	  latestFor(userId: string | number): ChatSession | undefined {
97	    // Ascending and stable, so of two sessions last active at the same moment, the one created later wins.
98	    return this.ownedBy(userId).sort(byActivity).at(-1)?.session;
99	  }
100	
101	  // Their own array, so a caller's sort never reorders the map's insertion order, which the sweep depends on.
102	  private ownedBy(userId: string | number): HeldSession[] {
103	    return [...this.sessions.values()].filter(held => held.session.userId === userId && !this.hasExpired(held));
104	  }
105	
106	  // Insertion order approximates age order, so the first live entry ends the sweep and the rest cost nothing.
107	  private sweepExpired(): void {
108	    for (const [sessionId, held] of this.sessions) {
109	      if (!this.hasExpired(held)) return;
110	      this.sessions.delete(sessionId);
111	    }
112	  }
113	
114	  // A session stamped with an unusable clock reading never ages out, rather than expiring immediately.
115	  private hasExpired(held: HeldSession): boolean {
116	    return Number.isFinite(held.createdAt) && Date.now() - held.createdAt > this.maxAgeMs;
117	  }
118	}
119	
120	// Ascending and stable, so latestFor's `.at(-1)` takes the session created later when two are last active together.
121	function byActivity(first: HeldSession, second: HeldSession): number {
122	  return lastActivity(first) - lastActivity(second);
123	}
124	
125	function summaryOf(held: HeldSession): SessionSummary {
126	  const {session} = held;
127	  return {
128	    sessionId: session.sessionId,
129	    createdAt: new Date(held.createdAt),
130	    updatedAt: new Date(lastActivity(held)),
131	    entryCount: session.entries.length,
132	  };
133	}
134	
135	// The store has no save to stamp, so activity is read off the entries; an unusable clock reading counts as none.
136	function lastActivity(held: HeldSession): number {
137	  const {entries} = held.session;
138	  const stamps = entries.map(entry => ('timestamp' in entry ? Date.parse(entry.timestamp) : Number.NaN));
139	  // Folded rather than spread into Math.max, whose argument list runs out past about 150,000 entries.
140	  return [held.createdAt, ...stamps].filter(Number.isFinite).reduce((latest, time) => Math.max(latest, time), 0);
141	}
