// Frames up to and including the first of `until`; a late answer is a failed wait naming what did arrive, never a hang.
const framesUntil = (client: WebSocket, until: string, timeoutMs = 1000): Promise<Frame[]> => {
  const seen: Frame[] = [];
  return new Promise<Frame[]>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`no ${until} arrived within ${timeoutMs}ms; frames seen: ${JSON.stringify(seen)}`)), timeoutMs);
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      seen.push(frame);
      if (frame.type === until) {
        clearTimeout(timer);
        resolve(seen);
      }
    });
