// Waits for a frame type, failing with the frames seen so far rather than hanging, so a missing answer is named.
const eventually = async (check: () => boolean, missing: string, seen: () => string): Promise<void> => {
  for (let waited = 0; waited < 2000 && !check(); waited += 10) {
    await new Promise(resolve => setTimeout(resolve, 10));
  }
  if (!check()) throw new Error(`${missing}; frames seen: ${seen()}`);
};

const expectFrame = (frames: Frame[], type: string): Promise<void> =>
  eventually(() => has(frames, type), `no ${type} arrived`, () => JSON.stringify(frames));

